// Public map tiles and remote geocoding are deliberately not bulk-cached.
const VERSION='pk-locator-v1.3.0';
const SHELL=['./','./index.html','./style.css?v=1.3.0','./app.js?v=1.3.0','./core.js?v=1.3.0','./national.js?v=1.3.0','./national-index.js?v=1.3.0','./data/national/manifest.json','./data/national/ES/overview.json','./config.json','./icon.svg','./manifest.webmanifest','./vendor/leaflet.js','./vendor/leaflet.css','./vendor/maplibre-gl.js','./vendor/maplibre-gl.css','./vendor/leaflet-maplibre-gl.js','./data/es-road-catalog.json','./data/es-ap7.json','./data/catalog.json','./data/official-pks.json','./data/Valencia.json','./data/Angers.json','./icons/icon-192.png','./icons/icon-512.png'];
self.addEventListener('install',event=>event.waitUntil(caches.open(VERSION).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('pk-locator-')&&k!==VERSION).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!url.pathname.startsWith(new URL('./',self.location.href).pathname))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();event.waitUntil(caches.open(VERSION).then(c=>c.put(event.request,copy)))}return response}).catch(()=>caches.match(event.request).then(r=>r||(event.request.mode==='navigate'?caches.match('./index.html'):Response.error()))))});
